:root{font-family:Arial,'Noto Sans TC',system-ui,sans-serif;color:#203f3a;background:#f5f0df}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overscroll-behavior:none}button,a{-webkit-tap-highlight-color:transparent;touch-action:manipulation}button{font:inherit;cursor:pointer}button:disabled{opacity:.45}button:focus-visible,a:focus-visible{outline:3px solid #dc693d;outline-offset:2px}
/* One active layout, scoped above shared admission styles. No legacy active/phase overrides. */
.pf-game.pf-high-jump .app{height:100dvh;min-height:0;max-width:1600px;margin:auto;padding:calc(8px + env(safe-area-inset-top)) calc(8px + env(safe-area-inset-right)) calc(8px + env(safe-area-inset-bottom)) calc(8px + env(safe-area-inset-left));display:grid;grid-template-rows:auto minmax(0,74fr) minmax(124px,26fr);gap:6px;overflow:hidden}
.pf-high-jump .pf-header h1 span{font-size:11px;font-weight:400}
.pf-game.pf-high-jump #stage{position:relative;overflow:hidden;min-height:0;min-width:0;border:1px solid #b9cfc0;border-radius:16px;background:#badbd0}
#world,#world canvas{width:100%;height:100%;display:block}.stage-label{position:absolute;left:12px;top:10px;font-size:12px;background:#fff9e5dd;padding:5px 8px;border-radius:8px}.stage-label span{display:inline-block;margin-left:10px;font-size:10px}.stage-label button{border:0;background:transparent;color:inherit;min-height:28px;min-width:28px}#count{position:absolute;left:50%;top:45%;transform:translate(-50%,-50%);font-size:90px;font-weight:900;color:#fff9d7;text-shadow:0 5px #39766a;pointer-events:none}#replayTag{position:absolute;right:12px;top:12px;background:#203f3a;color:#fff5dc;padding:8px;border-radius:6px;font-size:12px}
.control-panel{display:flex;flex-direction:column;justify-content:center;gap:10px;min-height:0;min-width:0}#prompt{margin:0;text-align:center;font-size:14px;line-height:1.4}.controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:clamp(20px,8vw,100px);min-width:0}.limb-group{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;min-width:0}.controls button{min-width:0;min-height:52px;border:1px solid #aab8a1;border-radius:12px;background:#fff9e6;color:#284f44;font-size:15px;font-weight:700;touch-action:none;user-select:none;overflow:hidden}.controls button.active{background:#f3aa65;transform:translateY(2px)}.controls kbd{font:700 15px Arial;margin-right:6px}.status{font-size:10px;color:#718172;text-align:center;margin:0;line-height:1.3}.eyebrow{font-size:10px;letter-spacing:2px;color:#748371}
dialog{position:fixed;width:min(480px,calc(100vw - 28px));max-height:calc(100dvh - 32px - env(safe-area-inset-top) - env(safe-area-inset-bottom));border:1px solid #bac7ac;border-radius:22px;padding:30px;background:#fff9e8;color:#23453c;overflow:auto;overscroll-behavior:contain;touch-action:pan-y;box-shadow:0 15px 80px #173b3f40}dialog::backdrop{background:#173b3f66;backdrop-filter:blur(4px)}dialog h2{font-size:35px;line-height:1.25;margin:8px 0 18px;letter-spacing:-1px}dialog p,dialog li{font-size:14px;line-height:1.7}dialog ol{padding-left:22px}dialog li{margin:12px 0}dialog button,.result-actions button{min-height:46px;border-radius:9px;border:1px solid #b1bd9c;padding:10px 15px;background:#f1efd9;color:#27463a;font-weight:700}.primary{background:#2d6e53!important;color:#fffbe4!important;border-color:#2d6e53!important}#start{width:100%;margin-top:10px}.result-score{font-size:56px;font-weight:900;color:#d86b38}.result-actions{display:flex;gap:8px;flex-wrap:wrap}#resultPhoto,#fallbackImage{width:100%;border-radius:10px}#fallback textarea{width:100%;min-height:150px;font:inherit;padding:10px;user-select:text}.lead{color:#6a7865}.pf-share-actions a{min-height:44px;text-decoration:none;display:flex;align-items:center;justify-content:center}#shareStatus{min-height:20px;font-size:12px}.game-error{padding:70px 25px;line-height:1.8}

@media(max-width:640px){.pf-game.pf-high-jump .pf-header{grid-template-columns:auto minmax(0,1fr);min-height:44px}.pf-game.pf-high-jump .pf-header nav{justify-self:end}.pf-game.pf-high-jump .pf-header nav button{font-size:12px;padding:0 5px}.pf-game.pf-high-jump .pf-header .pf-home{font-size:12px;padding:0 5px}.controls{gap:24px}.limb-group{gap:5px}.controls button{padding:5px 1px;font-size:13px}.controls kbd{margin-right:3px}#prompt{font-size:13px}.status{font-size:9px}}
@media(max-height:500px){.control-panel{gap:4px}.controls button{min-height:44px}#prompt{font-size:12px}.status{display:none}.pf-game.pf-high-jump .app{grid-template-rows:auto minmax(0,74fr) minmax(64px,26fr)}}

/* The download photo keeps its own aspect; optional result content scrolls instead of squeezing it. */
.pf-game.pf-high-jump #result{width:min(720px,calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)));height:fit-content;max-height:calc(100dvh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));padding:16px;display:flex;flex-direction:column;gap:10px;overflow:auto;scrollbar-gutter:stable;align-items:stretch}
.pf-game.pf-high-jump #result>*{flex-shrink:0}
.pf-game.pf-high-jump #result .result-summary{min-width:0;text-align:center}
.pf-game.pf-high-jump #result .eyebrow{font-size:10px;line-height:1.2;margin:0 0 3px}
.pf-game.pf-high-jump #result h2{font-size:21px;line-height:1.2;margin:0 0 3px}
.pf-game.pf-high-jump #result .result-score{font-size:clamp(30px,5vh,46px);line-height:1.08}
.pf-game.pf-high-jump #result #verdict{font-size:14px;line-height:1.35;margin:5px 0 0;overflow-wrap:anywhere}
.pf-game.pf-high-jump #result .result-scene{min-height:0;min-width:0;display:flex;align-items:center;justify-content:center}
.pf-game.pf-high-jump #result #resultPhoto{width:auto;height:auto;max-width:100%;max-height:300px;min-height:0;object-fit:contain;background:#beded1;border-radius:12px}
.pf-game.pf-high-jump #result .result-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:0;min-width:0}
.pf-game.pf-high-jump #result .result-actions button{font-size:15px;min-width:0;min-height:44px;padding:8px}
.pf-game.pf-high-jump #result .pf-share-actions{grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
.pf-game.pf-high-jump #result .pf-share-actions :is(button,a){font-size:12px;min-height:44px;padding:6px 4px}
.pf-game.pf-high-jump #result #shareStatus{font-size:11px;line-height:1.25;margin:0;min-height:0;text-align:center}
.pf-game.pf-high-jump #result #shareStatus:empty{display:none}
.pf-game.pf-high-jump #result #retryImage{font-size:12px;min-height:36px;padding:4px}
@media(max-height:500px) and (min-width:600px){
 .pf-game.pf-high-jump #result{width:min(860px,calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)));padding:12px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);grid-template-rows:auto auto auto;grid-auto-rows:max-content;gap:8px 12px;align-content:start}
 .pf-game.pf-high-jump #result .result-summary{grid-column:1;grid-row:1;align-self:center}
 .pf-game.pf-high-jump #result .result-scene{grid-column:2;grid-row:1/3}
 .pf-game.pf-high-jump #result #resultPhoto{max-height:240px}
 .pf-game.pf-high-jump #result .result-actions{grid-column:1;grid-row:2}
 .pf-game.pf-high-jump #result .pf-share-actions{grid-column:1/-1;grid-row:3}
 .pf-game.pf-high-jump #result #shareStatus{grid-column:1/-1;grid-row:4}
 .pf-game.pf-high-jump #result #retryImage{grid-column:1/-1}
 .pf-game.pf-high-jump #result :is(.pf-result-ranking,.pf-leaderboard){grid-column:1/-1}
}

/* Explicit persistent instructions, never removed when running starts. */
.pf-game.pf-high-jump #prompt{display:block!important;visibility:visible;flex-shrink:0;overflow-wrap:anywhere}

/* PlayFormosa admission contract. Import AFTER the game's own art stylesheet. */
.pf-game .pf-header{position:relative;inset:auto;z-index:auto;flex:none;display:grid;grid-template-columns:auto minmax(0,1fr) auto;align-items:center;gap:12px;width:100%;height:auto;min-height:48px;min-width:0;margin:0;padding:0;font-family:Arial,'Noto Sans TC',system-ui,sans-serif;}
.pf-game .pf-header .pf-home{display:inline-flex;align-items:center;justify-content:center;min-height:44px;min-width:44px;padding:0 8px;border:1px solid #bdc9b9;border-radius:10px;background:#fffdf4;color:#243d38;text-decoration:none;white-space:nowrap;font:700 14px/1.2 Arial,'Noto Sans TC',system-ui,sans-serif;letter-spacing:0;}
.pf-game .pf-header h1{display:block;min-width:0;margin:0;padding:0;border:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:18px;font-weight:800;line-height:1.3;letter-spacing:0;}
.pf-game .pf-header nav{display:flex;align-items:center;gap:6px;margin:0;}
.pf-game .pf-header nav button{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:4px;min-width:44px;min-height:44px;width:auto;height:44px;margin:0;padding:0 9px;border:1px solid #bdc9b9;border-radius:10px;background:#fffdf4;color:#243d38;font:700 14px/1 Arial,'Noto Sans TC',system-ui,sans-serif;white-space:nowrap;touch-action:manipulation;}
.pf-game .pf-header nav button[aria-pressed="true"]{background:#dff18d;border-color:#67825c;}
.pf-game .pf-header nav button:disabled{opacity:.45;cursor:not-allowed;}
.pf-game .pf-header :is(a,button):focus-visible,.pf-share-actions :is(a,button):focus-visible{outline:3px solid #dc683e;outline-offset:2px;}
.pf-game .pf-header #sound{min-width:44px;width:44px;}.pf-game .pf-header #soundLabel{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);}.pf-game .pf-header #sound .off{left:13px;top:21px;}
.pf-game.pf-long-jump{grid-template-rows:auto minmax(0,1fr);}
.pf-game.pf-hurdles{padding:calc(8px + env(safe-area-inset-top)) calc(8px + env(safe-area-inset-right)) calc(8px + env(safe-area-inset-bottom)) calc(8px + env(safe-area-inset-left));grid-template-rows:auto minmax(0,1fr) 24px;gap:8px;}
.pf-game :is(.shell,.game){max-width:none;width:100%;height:100dvh;min-height:0;margin:0;padding:calc(8px + env(safe-area-inset-top)) calc(8px + env(safe-area-inset-right)) calc(8px + env(safe-area-inset-bottom)) calc(8px + env(safe-area-inset-left));gap:8px;}
.pf-game .shell{display:flex;flex-direction:column;overflow:auto;}.pf-game .game-card{height:auto;display:flex;flex:1;flex-direction:column;min-height:0;max-width:1120px;width:100%;margin:0 auto;}.pf-game .stage{height:auto;min-height:0;flex:1;}.pf-game .game-card .topline{position:relative;inset:auto;pointer-events:auto;height:auto;min-height:48px;padding:8px 16px;flex:none;}.pf-game .game-card .topline h2{font-size:20px;margin:0;}.pf-game .game-card .bottomline{position:relative;inset:auto;max-width:none;flex:none;}.pf-game .shell>footer{flex:none;margin:0;padding:0 4px;}.pf-game #stage{min-height:0;}.pf-game .game>.fineprint{margin:0;min-height:22px;}.pf-game .game>.fineprint button{min-height:22px;}
.pf-game #helpBtn{min-width:44px;min-height:44px;}
.pf-game .pf-share-actions.pf-share-actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;}
.pf-game .pf-share-actions.pf-share-actions :is(button,a){display:flex;align-items:center;justify-content:center;grid-column:auto!important;grid-row:auto!important;min-height:44px;min-width:0;width:100%;margin:0;padding:10px 8px;border:1px solid #bdc9b9;border-radius:10px;background:#e7eddf;color:#243d38;text-align:center;text-decoration:none;font-size:14px;line-height:1.3;font-weight:700;overflow-wrap:anywhere;}
.pf-game .pf-share-actions.pf-share-actions [data-share="image"]{background:#dff18d;}.pf-game .pf-share-actions.pf-share-actions :disabled{opacity:.5;}
.pf-game .pf-result-dialog{position:fixed;inset:calc(12px + env(safe-area-inset-top)) calc(12px + env(safe-area-inset-right)) calc(12px + env(safe-area-inset-bottom)) calc(12px + env(safe-area-inset-left));margin:auto;transform:none;animation:none;width:min(560px,calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)));max-width:none;height:fit-content;max-height:calc(100dvh - 24px - env(safe-area-inset-top) - env(safe-area-inset-bottom));overflow:auto;overscroll-behavior:contain;touch-action:pan-y;padding:22px;border-radius:20px;display:block;}
.pf-game .pf-result-dialog:not([open]),.pf-game [hidden]{display:none!important;}
.pf-game .pf-result-dialog :is(button,a){min-height:44px;}.pf-game .pf-result-dialog button{touch-action:manipulation;}
.pf-game .pf-result-dialog h2{font-size:24px;line-height:1.4;margin:12px 0;overflow-wrap:anywhere;}.pf-game .pf-result-dialog p{font-size:14px;line-height:1.55;}.pf-game .pf-result-dialog .result-foot{display:block;font-size:11px;}.pf-game .pf-result-dialog .scoreline strong{font-size:58px;letter-spacing:-2px;}.pf-game .pf-result-dialog .result-mini{display:flex;font-size:12px;}.pf-game .pf-result-dialog .result-mini b{display:block;font-size:18px;}.pf-game .pf-result-dialog .judge-scores b{font-size:22px;}.pf-game .pf-result-dialog .platform-share-note{display:block;font-size:12px;line-height:1.5;}.pf-game .pf-result-dialog #resultPhoto{display:block;width:100%;height:auto;max-height:260px;object-fit:contain;border-radius:12px;background:#20372b;}.pf-game .pf-result-dialog #resultPhoto[hidden]{display:none;}
.pf-game .pf-result-dialog .result-panel{display:block;max-width:none;padding:0;background:none;box-shadow:none;}.pf-game .pf-result-dialog .result-actions{border:0;padding:0;}.pf-game .pf-result-dialog .result-summary{padding:0;}.pf-game .pf-result-dialog .private-note{line-height:1.5;}
.pf-game #platformImageDialog img{display:block;width:100%;height:auto;}.pf-game dialog textarea{width:100%;min-height:150px;font:inherit;user-select:text;}.pf-game .pf-result-dialog [role="status"]{overflow-wrap:anywhere;user-select:text;min-height:0;}
@media(max-width:640px){.pf-game .pf-header{grid-template-columns:minmax(0,1fr) auto;gap:2px 6px;}.pf-game .pf-header .pf-home{justify-self:start;}.pf-game .pf-header h1{grid-column:1/-1;grid-row:2;font-size:15px;padding:2px 8px;}.pf-game .pf-header nav{grid-column:2;grid-row:1;}.pf-game .pf-header nav button{padding:0 7px;font-size:13px;}.pf-game .pf-share-actions.pf-share-actions{grid-template-columns:1fr;}.pf-game .pf-result-dialog{padding:18px;}.pf-game .shell>footer{font-size:10px;}.pf-game .scoreboard{gap:12px;}.pf-game .scoreboard .best{padding-left:12px;}}
@media(max-height:480px) and (orientation:landscape){.pf-game .shell>footer{display:none;}.pf-game .game-card .topline{min-height:36px;padding:4px 12px;}.pf-game .game-card .bottomline{min-height:32px;padding:4px 12px;}.pf-game .pf-result-dialog{width:min(760px,calc(100vw - 24px - env(safe-area-inset-left) - env(safe-area-inset-right)));padding:16px 22px;}.pf-game .pf-result-dialog #resultPhoto{max-height:160px;}.pf-game .pf-share-actions.pf-share-actions{grid-template-columns:repeat(3,minmax(0,1fr));}}

/* Existing title/HUD positioning must not turn the shared bar into a floating icon. */
.pf-game .ready.overlay{overflow:auto;overscroll-behavior:contain;touch-action:pan-y;}.pf-game .ready .intro{margin:auto 0;}
.pf-game :is(.card.result,#overlay.result) button{min-height:44px;}

.pf-game .pf-header .pf-audio-status{position:static;inset:auto;grid-column:1/-1;max-width:none;min-width:0;z-index:auto;margin:0;padding:2px 8px;text-align:right;font-size:11px;line-height:1.4;overflow-wrap:anywhere;}

.pf-game .pf-result-dialog [tabindex="-1"]:focus{outline:2px solid currentColor;outline-offset:4px;}

/* Result hierarchy: play actions stay outside optional secondary statistics. */
.pf-game .pf-result-details{grid-column:1/-1;margin:12px 0;border:1px solid #bfcbbd;border-radius:12px;padding:0 12px;min-width:0;text-align:left;}
.pf-game .pf-result-details>summary{min-height:44px;display:flex;align-items:center;font-size:14px;line-height:1.5;font-weight:700;cursor:pointer;}
.pf-game .pf-result-details p{font-size:14px!important;line-height:1.6;overflow-wrap:anywhere;}
.pf-game .pf-result-play{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0;}
.pf-game .pf-result-play>button{flex:1 1 150px;min-height:44px;margin:0;}
.pf-game.pf-reaction-rod #againBtn{min-height:48px;}
.pf-game .pf-result-details :is(.result-stats>div>span,.judge-scores span,.result-mini>span){font-size:14px;line-height:1.5;overflow-wrap:anywhere;}
/* Optional entry details stay readable and easy to open without crowding core controls. */
.pf-game .entry-help{grid-column:1/-1;text-align:left;}
.pf-game .entry-help>summary{min-height:44px;display:flex;align-items:center;font-size:14px;line-height:1.5;cursor:pointer;}
.pf-game .entry-help p{font-size:14px;line-height:1.6;display:block;}
.pf-game [data-entry-operation]{font-size:18px!important;line-height:1.6!important;}
.pf-game [data-entry-operation] :is(b,strong,span){font-size:inherit;line-height:inherit;}
.pf-game #center:has([data-entry-goal]){overflow:auto;justify-content:flex-start;touch-action:pan-y;}
.pf-game #center:has([data-entry-goal])>[data-entry-goal]{margin-top:auto;}
.pf-game #center:has([data-entry-goal])>#start{margin-bottom:auto;flex-shrink:0;}

/* Result presentation adopts the same V2 material; scene, score and share pixels are unchanged. */
.pf-game .pf-result-dialog,.pf-game dialog#overlay.result{background:#fff9e9;color:#173f39;border:2px solid #174941;border-radius:24px;box-shadow:0 7px 0 #17494128,0 22px 70px #123c3e45;}
.pf-game .card.result{background:#fff9e9;color:#173f39;border:2px solid #174941;border-radius:24px;}
.pf-game :is(.pf-result-dialog,.card.result,dialog#overlay.result) :is(#again,#againBtn,#retry,#start){background:#ef945a;color:#123f3c;border:2px solid #174941;border-radius:16px;box-shadow:0 4px 0 #174941;min-height:48px;font-weight:800;}
.pf-game :is(.pf-result-dialog,.card.result,dialog#overlay.result) :is(.pf-result-ranking,#replay,#view-final,#replay-last,#watchReplay){min-height:44px;border-radius:14px;}

:root{color-scheme:light;--cream:#fff9e9;--green:#174941;--deep:#173f39;--orange:#ef945a;--gold:#f4dda7;--mint:#dcebdd;--line:#c5d2bb;--muted:#66786a}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--cream);color:var(--green);font-family:system-ui,-apple-system,'Noto Sans TC',sans-serif}
body{padding:max(16px,env(safe-area-inset-top)) max(20px,env(safe-area-inset-right)) max(12px,env(safe-area-inset-bottom)) max(20px,env(safe-area-inset-left));user-select:none;-webkit-user-select:none;-webkit-touch-callout:none}
main{height:100%;height:100dvh;max-height:100%;max-width:1080px;margin:auto;display:grid;grid-template-rows:auto minmax(100px,1fr) auto auto auto auto;gap:12px}
button,select{font:inherit;touch-action:manipulation}
button{min-height:44px;border:1.5px solid transparent;border-radius:14px;padding:10px 20px;font-size:15px;font-weight:800;cursor:pointer;white-space:nowrap;line-height:1.3;transition:background .15s,box-shadow .15s,transform .15s}
button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--green);outline-offset:3px}
button[hidden],[hidden]{display:none!important}
button:disabled,select:disabled{cursor:not-allowed;opacity:.55}
.primary{color:var(--deep);background:var(--orange);border-color:#d78048;box-shadow:0 3px 0 #b76d3c}
.primary:hover{background:#f6a56d}
.primary:active{transform:translateY(2px);box-shadow:0 1px 0 #b76d3c}
.primary>span{float:right;margin-left:18px}
.secondary{color:var(--green);background:var(--mint);border-color:#bfd2bb}
.secondary:hover{background:#cedfca}
.quiet-button{background:transparent;color:var(--green);border-color:#d5d9c7}
.quiet-button:hover{background:#f3ecd9}
.game-header{display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0}
.eyebrow{font-size:10px;letter-spacing:1.6px;color:var(--muted);font-weight:800}
h1{font-size:30px;line-height:1.2;margin:5px 0 0;letter-spacing:.8px}
h1 span{display:inline-block;font-size:12px;letter-spacing:.4px;margin-left:8px;padding:5px 9px;background:var(--gold);border-radius:7px;vertical-align:middle}
.header-tools{display:flex;align-items:center;gap:12px;flex-shrink:0}
.mode-status{font-size:11px;color:var(--muted);white-space:nowrap}
.menu-button{display:flex;align-items:center;justify-content:center;gap:7px;background:var(--green);color:var(--cream);padding:8px 13px;font-size:13px;min-width:76px}
.menu-button>span:first-child{font-size:18px;font-weight:500;line-height:1}
.scene-card{min-height:0;display:flex;flex-direction:column;overflow:hidden;border:1.5px solid #b9cdb6;border-radius:22px;background:#e4eddf;box-shadow:0 2px 0 #17494108}
.scene-heading{flex:none;display:flex;align-items:center;gap:10px;padding:10px 15px 3px;min-height:37px;font-size:14px}
.scene-heading #badge{font-size:10px;background:var(--cream);border:1px solid #d2d7be;border-radius:6px;padding:4px 8px;color:var(--green);white-space:nowrap;font-weight:800}
.scene-heading strong{line-height:1.35}
.scene-tag{margin-left:auto;font-size:11px;color:var(--muted);letter-spacing:.4px}
.canvas-wrap{flex:1;min-height:0;position:relative}
canvas{width:100%;height:100%;display:block}
.scene-caption{text-align:center;font-size:11px;color:var(--muted);padding:2px 8px 8px;flex:none}
.score-row{display:grid;grid-template-columns:1.2fr 1fr 1fr;align-items:center;border:1.5px solid #dbddc9;border-radius:16px;background:#fffdf6;padding:9px 20px;gap:20px}
.score-row label{display:block;font-size:11px;letter-spacing:.4px;color:var(--muted);font-weight:650}
.score-row strong{display:block;font-variant-numeric:tabular-nums;font-size:23px;font-weight:800;line-height:1.2;margin-top:3px}
.score-row .score-main strong{font-size:34px;letter-spacing:.5px}
.score-row small{font-size:13px;letter-spacing:0;font-weight:600}
.score-best,.score-drop{border-left:1px solid #e0e0cd;padding-left:24px}
.score-best label span{font-size:9px;margin-left:4px}
.control-section{min-width:0}
.instruction{display:flex;justify-content:space-between;gap:8px;align-items:center;margin:0 2px 8px;min-height:22px}
.instruction strong{font-size:18px;line-height:1.4;letter-spacing:-.3px}
.instruction>span{color:var(--muted);font-size:12px;white-space:nowrap}
#pad{height:122px;border:2px solid #b2c5a8;border-radius:20px;position:relative;overflow:hidden;touch-action:none;background:#fffcf1;cursor:grab;outline-offset:3px;isolation:isolate}
#pad:focus-visible{outline:3px solid var(--green)}
#pad:active{cursor:grabbing}
.pad-track{position:absolute;left:11%;right:11%;top:50%;height:3px;transform:translateY(-50%);background:repeating-linear-gradient(to right,#cfdbc1 0,#cfdbc1 9px,transparent 9px,transparent 16px)}
.gate{position:absolute;top:0;bottom:0;width:18%;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:2px;z-index:2;pointer-events:none;transition:background .15s,box-shadow .15s}
.gate-prop{height:43px;width:62px;max-width:82%;object-fit:contain;pointer-events:none;filter:drop-shadow(0 2px 0 #1749410a)}
.gate span{font-size:14px;font-weight:850;white-space:nowrap;line-height:1.3}
.gate small{font-size:10px;white-space:nowrap;color:var(--muted)}
.home{left:0;border-right:2px dashed #b3c79d;background:var(--mint)}
.far{right:0;border-left:2px dashed #d5bb80;background:#f9ebc7}
.travel-label{position:absolute;left:23%;right:23%;top:50%;transform:translateY(-50%);display:flex;flex-direction:column;gap:7px;align-items:center;color:#637b5e;font-size:17px;font-weight:800;pointer-events:none;text-align:center}
.travel-label>span{background:#fffcf1;padding:0 8px;line-height:1.4}
.travel-label>small{font-size:12px;font-weight:650;background:#fffcf1;padding:0 8px;color:var(--muted)}
#thumb{position:absolute;top:50%;width:34px;height:34px;border-radius:50%;transform:translate(-50%,-50%);left:10%;z-index:4;pointer-events:none;background:var(--orange);border:4px solid var(--cream);box-shadow:0 0 0 2px #bc7445,0 3px 8px #a16c4222;opacity:0}
#thumb i{display:block;width:6px;height:6px;margin:10px;border-radius:50%;background:var(--cream)}
body[data-phase="armed"] #thumb,body[data-phase="outbound"] #thumb,body[data-phase="returning"] #thumb,body[data-phase="success"] #thumb,body[data-phase="demo"] #thumb{opacity:1}
body[data-phase="armed"] .home{box-shadow:inset 0 0 0 3px #4f805b}
body[data-phase="outbound"] .far{background:#f8d789;box-shadow:inset 0 0 0 3px #bc8a39}
body[data-phase="outbound"] .home .gate-prop{opacity:.58}
body[data-phase="returning"] .home{background:#c4dfb8;box-shadow:inset 0 0 0 3px #44845b}
body[data-phase="returning"] .home .gate-prop{transform:rotate(-6deg) scale(1.08)}
body[data-phase="returning"] #instruction{color:#236343}
body[data-phase="returning"] #controlArrow{color:var(--cream);background:var(--green);border-radius:8px;padding:3px 10px}
body[data-phase="returning"] .travel-label>small{visibility:hidden}
body[data-phase="success"] #pad{border-color:#5e8f64}
body[data-phase="success"] .home{background:#c4dfb8}
body[data-phase="failed"] #pad,body[data-phase="cancelled"] #pad{border-color:#c79873}
body[data-phase="failed"] .gate-prop,body[data-phase="cancelled"] .gate-prop{opacity:.65}
#demoVeil{position:absolute;inset:0;z-index:5;display:flex;align-items:flex-end;justify-content:center;padding-bottom:6px;background:#fff5db15;color:#617654;font-size:10px;pointer-events:none}
body:not([data-phase="demo"]) #demoVeil{display:none}
.actions{display:flex;align-items:stretch;gap:8px;padding-bottom:3px}
body[data-overlay="entry"] .actions,body[data-overlay="result"] .actions,body[data-overlay="help"] .actions{visibility:hidden}
.actions .primary{flex:1;min-width:0}
.actions .secondary,.actions .quiet-button{flex:0 0 auto}
footer{font-size:10px;color:var(--muted);display:flex;justify-content:space-between;gap:12px;line-height:1.4}
/* Native dialogs keep focus inside their own actions; the game is never paused. */
dialog{border:1.5px solid #b9c9ae;border-radius:22px;width:calc(100% - 32px);max-width:440px;max-height:calc(100dvh - 28px - env(safe-area-inset-top) - env(safe-area-inset-bottom));padding:0;background:var(--cream);color:var(--green);box-shadow:0 18px 80px #173f3940;overflow:auto;overscroll-behavior:contain}
dialog::backdrop{background:#173f3966;backdrop-filter:blur(4px)}
.ticket-top{position:relative;background:var(--gold);padding:25px 26px 22px;border-bottom:1.5px dashed #c0ad7d}
.ticket-kicker{font-size:10px;letter-spacing:1.5px;color:#516546;font-weight:850}
.close-button{position:absolute;right:10px;top:10px;padding:0;min-width:44px;width:44px;height:44px;font-size:28px;font-weight:450;background:#fff9e963;color:var(--green);border:1px solid #17494115;border-radius:50%;line-height:1}
.close-button:hover{background:var(--cream)}
.ticket-top h2{margin:12px 0 6px;font-size:38px;line-height:1.2;letter-spacing:1px}
.entry-dialog h2 span{display:inline-block;font-size:13px;letter-spacing:.7px;margin-left:11px;vertical-align:middle;border:1px solid #17494145;border-radius:6px;padding:5px 7px}
.ticket-top p{font-size:14px;margin:0;line-height:1.65;color:#46614b}
.ticket-body{padding:20px 26px 19px}
.entry-route{display:flex;align-items:center;justify-content:center;gap:30px;padding:0 0 16px}
.entry-route img{width:76px;height:62px;object-fit:contain}
.entry-route>span{display:flex;flex-direction:column;gap:9px;font-size:13px;color:var(--muted)}
.entry-route b{font-weight:700;white-space:nowrap}
.entry-steps{list-style:none;display:flex;flex-direction:column;gap:14px;margin:0 0 21px;padding:0}
.entry-steps li{display:flex;align-items:flex-start;gap:11px}
.entry-steps li>span{width:25px;height:25px;display:grid;place-items:center;background:var(--mint);border-radius:50%;flex:none;font-size:12px;font-weight:850;margin-top:1px}
.entry-steps strong{font-size:18px;line-height:1.45;display:block;letter-spacing:-.4px}
.entry-steps small{display:block;font-size:12px;color:var(--muted);line-height:1.65;margin-top:2px}
.entry-buttons{display:grid;grid-template-columns:1fr;gap:9px}
.entry-buttons>.primary{grid-column:1/-1;min-height:52px;font-size:18px;margin-bottom:3px}
.ticket-note{font-size:10px;text-align:center;line-height:1.5;color:var(--muted);margin:14px 0 0}
.result-top{text-align:center;padding-top:26px}
.result-top>.ticket-kicker{display:block;padding-right:14px}
.result-top h2{font-size:22px;line-height:1.4;margin:18px 0 0;letter-spacing:0}
.result-summary{display:flex;align-items:center;justify-content:center;gap:14px;margin:12px 0 6px;min-width:0}
.result-portrait{display:block;width:104px;height:104px;flex:none;object-fit:contain;border-radius:18px;background:#fff9e98c}
.result-time{font-size:58px;line-height:1.2;font-weight:900;letter-spacing:-2px;font-variant-numeric:tabular-nums;margin:0;white-space:nowrap;min-width:0}
.result-time>strong{font:inherit;letter-spacing:inherit}
.result-time small{font-size:22px;font-weight:700;letter-spacing:0}
.result-top p{font-size:13px}
.result-records{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:15px;text-align:center;padding:4px 0 12px;border-bottom:1px solid #dcdcc7}
.result-records>div+div{border-left:1px solid #dcdcc7}
.result-records span{display:block;font-size:11px;color:var(--muted);margin-bottom:7px}
.result-records strong{font-size:20px;font-variant-numeric:tabular-nums;line-height:1.35}
#resultDelta{display:block;font-size:12px;line-height:1.5;overflow-wrap:anywhere}
.result-mode{display:flex;justify-content:space-between;align-items:center;font-size:12px;padding:10px 0 12px;color:var(--muted)}
.result-mode strong{background:var(--mint);color:var(--green);font-size:11px;padding:5px 9px;border-radius:6px}
.result-buttons{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:8px}
.result-buttons>button{min-height:44px;padding:10px 8px;font-size:14px}
.result-buttons>.primary{font-size:15px}
.result-buttons>.primary>span{margin-left:6px}
.result-status{font-size:11px;line-height:1.5;text-align:center;color:var(--green);margin:8px 0 0}
.result-status:empty{display:none}
.result-dialog .ticket-note{margin-top:10px}
.info-dialog{padding:24px}
.info-header h2{font-size:23px;line-height:1.4;margin:10px 0 18px;letter-spacing:-.4px}
.help-steps{padding-left:22px;margin:0 0 20px}
.help-steps li{font-size:15px;line-height:1.75;padding-left:4px;margin-bottom:7px}
.settings-panel{background:#f1f1df;border:1px solid #d4d9bd;border-radius:14px;padding:12px 14px;margin-bottom:14px}
.mode-label,.sound-setting{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:13px;font-weight:700}
.sound-setting{margin-top:10px;padding-top:10px;border-top:1px solid #d6dbc4}
select{border:1px solid #b8c8ae;border-radius:9px;background:#fffdf4;padding:9px 8px;color:var(--green);font-size:13px;font-weight:700;min-height:44px;min-width:0;max-width:68%}
.sound-setting button{font-size:13px;padding:8px 14px}
.fine-print{font-size:12px;line-height:1.7;color:var(--muted);margin-bottom:18px}
.fine-print summary{cursor:pointer;min-height:44px;display:flex;align-items:center;font-weight:700;color:var(--green);gap:8px}
.fine-print summary::before{content:'＋';font-size:16px}
.fine-print[open] summary::before{content:'−'}
.fine-print p{margin:4px 0 12px}
.info-dialog>#closeInfo{width:100%;min-height:48px}
/* Separate canvases preserve playable fallback after WebGL allocation fails. */
#scene3d,#demo3d{display:none;width:100%;height:100%}
#demo3d{object-fit:contain;background:#eee9d9}
body[data-renderer="webgl"] #scene3d{display:block}
body[data-renderer="webgl"] #scene{display:none}
body[data-renderer="fallback"][data-phase="demo"]:not([data-video="failed"]) #demo3d{display:block}
body[data-renderer="fallback"][data-phase="demo"]:not([data-video="failed"]) #scene{display:none}
body[data-renderer="loading"] .scene-caption{color:#846645}
.fallback-badge{display:none;position:absolute;left:8px;bottom:6px;z-index:3;pointer-events:none;font-size:9px;font-weight:650;color:var(--green);background:#fff9e9f2;border:1px solid #b9cdb6;border-radius:6px;padding:3px 6px}
body[data-renderer="fallback"] .fallback-badge{display:block}
body[data-renderer="fallback"][data-phase="demo"] .fallback-badge{bottom:38px}
@media(max-width:600px){
  body{padding:max(10px,env(safe-area-inset-top)) max(12px,env(safe-area-inset-right)) max(8px,env(safe-area-inset-bottom)) max(12px,env(safe-area-inset-left))}
  main{gap:9px}
  h1{font-size:26px}h1 span{font-size:10px;margin-left:5px;padding:5px 7px}
  .eyebrow{font-size:8px;letter-spacing:1.1px}
  .header-tools{gap:6px;align-items:flex-end}.mode-status{font-size:9px;max-width:75px;text-align:right;white-space:normal;line-height:1.5;padding-bottom:4px}
  .menu-button{min-width:48px;width:48px;padding:8px;border-radius:12px}.menu-button>span:last-child{display:none}
  .scene-heading{font-size:12px;padding:9px 11px 2px;gap:7px;min-height:33px}.scene-tag{display:none}.scene-card{border-radius:18px}
  .score-row{padding:8px 12px;gap:9px}.score-row label{font-size:10px}.score-row .score-main strong{font-size:28px}.score-row strong{font-size:20px}.score-row small{font-size:11px}
  .score-best,.score-drop{padding-left:12px}.score-best label span{display:none}
  .instruction{display:block;margin-bottom:7px;min-height:0}.instruction strong{font-size:16px;letter-spacing:-.4px;display:block}.instruction>span{font-size:10px;display:block;margin-top:2px}
  #pad{height:118px;border-radius:17px}.gate-prop{height:37px;width:53px}.gate span{font-size:12px;letter-spacing:-.4px}.gate small{font-size:8px;letter-spacing:-.3px}
  .travel-label{font-size:15px;gap:6px}.travel-label>small{font-size:10px}.travel-label>span{padding:0 5px}
  #demoVeil{font-size:9px;padding-bottom:5px}
  .actions{gap:6px}.actions button{font-size:13px;padding:10px 13px}.actions .primary>span{margin-left:10px}
  footer{font-size:9px}footer>span:last-child{display:none}
  /* Narrow result tickets need a compact hero even on tall phone screens. */
  .result-summary{gap:10px}.result-portrait{width:82px;height:82px;border-radius:14px}.result-time{font-size:46px}.result-time small{font-size:17px}
}
@media(max-width:350px){
  h1{font-size:24px}h1 span{font-size:9px;margin-left:3px;padding:4px 6px}.header-tools{gap:4px}.mode-status{font-size:8px;max-width:61px}.eyebrow{font-size:7px}
  .instruction strong{font-size:15px;letter-spacing:-.5px}.gate span{font-size:10px}.gate small{font-size:8px}.travel-label{font-size:13px}
  .actions button{padding-left:10px;padding-right:10px;font-size:12px}
  .ticket-body{padding-left:19px;padding-right:19px}.ticket-top{padding-left:19px;padding-right:19px}.entry-steps strong{font-size:16px}.entry-steps small{font-size:11px}.entry-route{gap:24px}
  .info-dialog{padding:20px}.mode-label,.sound-setting{font-size:12px;gap:7px}select{font-size:12px}.result-records strong{font-size:18px}
}
@media(max-height:650px) and (orientation:portrait){
  body{padding-top:max(8px,env(safe-area-inset-top));padding-bottom:max(6px,env(safe-area-inset-bottom))}main{gap:7px}
  h1{font-size:23px;margin-top:3px}.eyebrow{font-size:7px}.scene-caption{display:none}.scene-heading{min-height:29px;padding-top:6px}
  .score-row{padding-top:5px;padding-bottom:5px}.score-row .score-main strong{font-size:26px}.score-row strong{font-size:18px}
  #pad{height:100px}.gate-prop{height:31px}.instruction{margin-bottom:5px}.instruction>span{margin-top:0}.travel-label{gap:4px}footer{font-size:8px}
}
