@media(prefers-reduced-motion:reduce){button,.gate{transition:none}dialog::backdrop{backdrop-filter:none}}

/* The original one-page layout stays in charge; platform additions are in-flow. */
.platform-return{display:flex;align-items:center;justify-content:center;min-height:44px;padding:10px 12px;border:1.5px solid #d5d9c7;border-radius:14px;text-decoration:none;font-size:13px;font-weight:700;text-align:center}
.platform-return:focus-visible{outline:3px solid var(--green);outline-offset:3px}
