.ranking-scroll{min-height:0;overflow:auto;overscroll-behavior:contain;padding:18px 22px;scroll-padding:18px;-webkit-overflow-scrolling:touch}
.ranking-scroll:focus-visible,.ranking-dialog input:focus-visible{outline:3px solid var(--green);outline-offset:2px}
.ranking-modes{display:grid;grid-template-columns:1fr 1fr;gap:8px}
