.ranking-rule,#rankingPrivacy{font-size:12px;line-height:1.7;color:var(--muted);overflow-wrap:anywhere}
.ranking-own{background:var(--mint);border-radius:12px;padding:12px 14px}
.ranking-own h3{margin:0 0 7px;font-size:13px}.ranking-own p{margin:5px 0 0;font-size:12px;line-height:1.5;overflow-wrap:anywhere}.ranking-own strong{font-size:24px;font-variant-numeric:tabular-nums}
.ranking-status{font-size:12px;line-height:1.65;margin:12px 0;overflow-wrap:anywhere}.ranking-status:empty{display:none}
.ranking-entries{list-style:none;margin:12px 0;padding:0}
.ranking-entries li{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;gap:8px;padding:12px 0;border-bottom:1px solid #dedfcb;font-size:13px}
.ranking-place{font-weight:800;text-align:center}.ranking-name{overflow-wrap:anywhere}.ranking-entries strong{font-size:13px;white-space:nowrap;font-variant-numeric:tabular-nums}.ranking-entries .is-me{background:#dcebdd70}
.ranking-frozen{font-size:17px;font-weight:850;line-height:1.6;margin:0 0 12px}.ranking-nickname{display:block;font-size:14px;font-weight:750;margin:16px 0 8px}
#rankingNickname{display:block;width:100%;min-height:46px;padding:10px 12px;border:1.5px solid #b8c8ae;border-radius:10px;background:#fffdf4;color:var(--green);font:16px/1.4 system-ui,sans-serif;user-select:text;-webkit-user-select:text}
.ranking-consent{display:flex;align-items:center;gap:10px;min-height:48px;font-size:12px;line-height:1.6;margin:12px 0;cursor:pointer}
.ranking-consent input{width:22px;height:22px;margin:11px 0;flex:none;accent-color:var(--green)}
#rankingSubmit,#rankingRefresh{width:100%;min-height:44px;white-space:normal}
.ranking-footer{display:block;flex:none;padding:10px 22px;border-top:1px solid #dedfcb;background:var(--cream)}
.ranking-footer button{width:100%;min-height:44px}
@media(max-height:400px){.ranking-header{padding:10px 16px}.ranking-header h2{font-size:20px;margin-top:4px;margin-bottom:4px}.ranking-header p{font-size:11px}.ranking-scroll{padding:12px 16px}.ranking-footer{padding:8px 16px}}
@media(max-width:350px){.ranking-header,.ranking-scroll{padding-left:16px;padding-right:16px}.ranking-frozen{font-size:15px}.ranking-entries li{gap:5px;font-size:12px}.ranking-entries strong{font-size:12px}}

/* Match the platform toolbar while keeping the single-gesture game layout. */
.game-header{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:12px}
.game-header .pf-home{display:flex;align-items:center;justify-content:center;min-width:44px;min-height:44px;padding:8px 10px;border:1.5px solid #d5d9c7;border-radius:12px;color:var(--green);font-size:13px;font-weight:750;text-decoration:none;white-space:nowrap}
.game-header .pf-home:focus-visible{outline:3px solid var(--green);outline-offset:3px}
.header-tools{gap:6px}.header-tools>button{min-width:44px;min-height:44px;padding:9px 12px;font-size:13px}.header-tools .mode-status{display:none}
.instruction strong{font-size:21px;line-height:1.45}.instruction>span{font-size:14px}
.entry-steps strong{font-size:20px}.entry-steps small{font-size:14px}.help-steps li{font-size:16px}
