@media(max-width:600px) and (orientation:portrait){
 .game-header{grid-template-columns:auto 1fr;gap:7px}.game-header .pf-home{grid-column:1;grid-row:1;justify-self:start}.game-header .header-tools{grid-column:2;grid-row:1;justify-self:end}.pf-game.pf-fast-hands .game-header>.pf-studio-heading{grid-column:1/-1;grid-row:2}.game-header h1{font-size:25px}.game-header .eyebrow{display:none}.header-tools .menu-button{width:44px;min-width:44px}.instruction strong{font-size:18px;letter-spacing:-.4px}.instruction>span{font-size:12px}.entry-steps strong{font-size:19px}.entry-steps small{font-size:13px}
}
@media(max-height:550px) and (orientation:landscape){
 .game-header{grid-template-columns:auto minmax(0,1fr) auto;gap:8px}.game-header h1{font-size:21px}.game-header h1 span{display:none}.game-header .pf-studio-live{font-size:9px}.header-tools>button{padding:8px 10px;font-size:12px}.header-tools .menu-button{min-width:44px;width:44px}.header-tools .menu-button>span:last-child{display:none}.instruction strong{font-size:15px;line-height:1.45}.instruction>span{font-size:11px}.entry-steps strong{font-size:17px}.entry-steps small{font-size:12px}
}

body[data-playback="replay"] #pad{cursor:default;border-style:dashed}body[data-playback="replay"] #thumb{opacity:1}

/* Sharing stays in the result ticket; desktop retains its PNG download. */
.result-share-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px;padding-top:12px;border-top:1px solid #dcdcc7}
.result-share-actions>a,.result-share-actions>button{display:flex;align-items:center;justify-content:center;min-height:44px;padding:10px 8px;font-size:14px;font-weight:750;text-align:center;text-decoration:none;white-space:normal;line-height:1.4}
.result-share-actions>a{border:1.5px solid #c5d2bb;border-radius:10px;background:var(--mint);color:var(--green)}
.result-share-actions>a:focus-visible{outline:3px solid var(--green);outline-offset:3px}
.result-share-actions>a:not([href]){opacity:.5;pointer-events:none}
.result-share-actions>#resultCopy{grid-column:1/-1}
.share-fallback{margin-top:12px;padding:12px;border:1px solid #c5d2bb;border-radius:12px;background:#fffdf6}
.share-fallback[hidden],.share-fallback>[hidden]{display:none}
.share-fallback img{display:block;width:100%;height:auto;max-width:360px;margin:0 auto 12px;user-select:auto;-webkit-user-select:auto;-webkit-touch-callout:default}
.share-fallback textarea{width:100%;min-height:130px;padding:10px;margin-bottom:10px;resize:vertical;border:1px solid #c5d2bb;border-radius:8px;font:14px/1.6 system-ui,sans-serif;color:var(--green);background:white;user-select:text;-webkit-user-select:text;-webkit-touch-callout:default}
.share-fallback button{width:100%;min-height:44px}
@media(max-height:550px),(max-width:350px){.result-share-actions{gap:6px;margin-top:8px;padding-top:8px}.result-share-actions>a,.result-share-actions>button{font-size:12px;padding:8px 6px}}

/* A larger desktop stage with supporting controls beside it. The continuous
   gesture track keeps the original main width, height and percentage gates. */
@media(min-width:1000px) and (min-height:680px){
  .pf-fast-hands main{grid-template-columns:minmax(0,1fr) 260px;grid-template-rows:auto minmax(0,1fr) auto auto auto;grid-template-areas:"header header" "scene scores" "scene actions" "control control" "footer footer"}
  .pf-fast-hands .game-header{grid-area:header}
  .pf-fast-hands .scene-card{grid-area:scene}
  .pf-fast-hands .score-row{grid-area:scores;align-self:start;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px 12px;padding:20px}
  .pf-fast-hands .score-main{grid-column:1/-1}
  .pf-fast-hands .score-best{border-left:0;padding-left:0}
  .pf-fast-hands .score-drop{padding-left:12px}
  .pf-fast-hands .score-row .score-main strong{font-size:40px}
  .pf-fast-hands .actions{grid-area:actions;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;align-self:end}
  .pf-fast-hands .actions button{flex:none;min-height:48px;padding:10px 8px;font-size:13px}
  .pf-fast-hands .actions .primary{grid-column:1/-1;font-size:15px}
  .pf-fast-hands .control-section{grid-area:control}
  .pf-fast-hands main>footer{grid-area:footer}
}

/* Keep the complete standard result ticket on one desktop screen. */
@media(min-width:1000px) and (min-height:560px){
 .result-dialog{width:calc(100% - 48px);max-width:900px;max-height:calc(100dvh - 32px)}
 .result-dialog[open]{display:grid;grid-template-columns:minmax(0,.82fr) minmax(0,1.25fr)}
 .result-dialog .result-top{display:flex;flex-direction:column;justify-content:center;padding:24px 22px;border-bottom:0;border-right:1.5px dashed #c0ad7d}
 .result-dialog .ticket-kicker{font-size:10px}.result-dialog .result-top h2{font-size:23px;margin-top:16px}
 .result-dialog .result-summary{flex-direction:column;gap:8px;margin:12px 0 8px}.result-dialog .result-portrait{width:118px;height:118px}.result-dialog .result-time{font-size:52px}.result-dialog .result-time small{font-size:19px}.result-dialog .result-top p{font-size:12px}
 .result-dialog .ticket-body{padding:20px 22px}.result-dialog .result-records{padding-bottom:10px}.result-dialog .result-records span{margin-bottom:5px}.result-dialog .result-mode{padding:8px 0}.result-dialog .result-buttons{gap:7px}.result-dialog .result-buttons>button{min-height:44px;font-size:12px;padding:8px}
 .result-dialog .result-share-actions{margin-top:9px;gap:6px}.result-dialog .result-share-actions>a,.result-dialog .result-share-actions>button{min-height:44px;padding:8px 5px;font-size:11px}
 .result-dialog .ticket-body>.level-switch{margin-top:9px;padding-top:9px}.result-dialog .ticket-note{margin-top:8px;font-size:10px}.result-dialog .pf-studio-result{margin-top:8px;font-size:9px}
 .result-dialog .share-fallback:not([hidden]){max-height:170px;overflow:auto}
}

